-- ──────────────────────────────────────────────────────────
-- VERIFICACION FINAL
-- ──────────────────────────────────────────────────────────
SELECT 'clientes'           AS tabla, COUNT(*) AS registros FROM clientes          UNION ALL
SELECT 'camiones',                    COUNT(*)              FROM camiones           UNION ALL
SELECT 'choferes',                    COUNT(*)              FROM choferes           UNION ALL
SELECT 'destinos_cliente',            COUNT(*)              FROM destinos_cliente   UNION ALL
SELECT 'viajes',                      COUNT(*)              FROM viajes             UNION ALL
SELECT 'cuenta_corriente',            COUNT(*)              FROM cuenta_corriente   UNION ALL
SELECT 'cargas_combustible',          COUNT(*)              FROM cargas_combustible UNION ALL
SELECT 'movimientos_caja',            COUNT(*)              FROM movimientos_caja   UNION ALL
SELECT 'costos_fijos',                COUNT(*)              FROM costos_fijos       UNION ALL
SELECT 'tareas',                      COUNT(*)              FROM tareas             UNION ALL
SELECT 'remitos',                     COUNT(*)              FROM remitos            UNION ALL
SELECT 'multas',                      COUNT(*)              FROM multas             UNION ALL
SELECT 'gastos_camion',               COUNT(*)              FROM gastos_camion      UNION ALL
SELECT 'facturas',                    COUNT(*)              FROM facturas
ORDER BY tabla;
